'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Bool = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Bool, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is a `toString` method', function test( t ) {
	t.strictEqual( hasOwnProp( Bool.prototype, 'toString' ), true, 'has property' );
	t.strictEqual( isFunction( Bool.prototype.toString ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a boolean object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Bool.prototype.toString.call( value );
		};
	}
});

tape( 'the method returns a string representation of a `Boolean` object (true)', function test( t ) {
	var b = new Bool( true );
	t.strictEqual( b.toString(), 'true', 'returns expected value' );
	t.end();
});

tape( 'the method returns a string representation of a `Boolean` object (false)', function test( t ) {
	var b = new Bool( false );
	t.strictEqual( b.toString(), 'false', 'returns expected value' );
	t.end();
});

tape( 'the method returns a string representation of a `Boolean` object (no argument)', function test( t ) {
	var b = new Bool();
	t.strictEqual( b.toString(), 'false', 'returns expected value' );
	t.end();
});
